import React from 'react';

import { valueContent } from './SeriesItem.sty.js';
import { BubbleShape } from '../../../../tooltip-atoms/shapes/BubbleShape.js';
import { MultiDataPointShape } from '../../../../tooltip-atoms/shapes/MultiDataPointShape.js';
import { SingleDataPointShape } from '../../../../tooltip-atoms/shapes/SingleDataPointShape.js';
import { TooltipText } from '../../../section-components/atoms/TooltipText.js';
import { TooltipInfoContent } from '../../../section-components/TooltipInfoContent.js';
import { TooltipItem } from '../../../section-components/TooltipItem.js';
import { TooltipSymbolContent } from '../../../section-components/TooltipSymbolContent.js';
import { TooltipValueContent } from '../../../section-components/TooltipValueContent.js';

export type Variant = 'single' | 'multi' | 'bubble';

export interface SeriesItemProps {
  color: string;
  name: string;
  value: string | string[];
  variant?: Variant;
  actions?: () => React.ReactElement;
}

export const SeriesItem = (props: SeriesItemProps) => {
  const { color, name, value, variant = 'single', actions } = props;

  const SYMBOL: Record<Variant, React.JSX.Element> = {
    single: <SingleDataPointShape color={color} />,
    multi: <MultiDataPointShape color={color} />,
    bubble: <BubbleShape color={color} />,
  };

  const multipleValues = Array.isArray(value);

  return (
    <TooltipItem actions={actions}>
      <TooltipSymbolContent>{SYMBOL[variant] ?? null}</TooltipSymbolContent>
      <TooltipInfoContent>
        <TooltipText>{name}</TooltipText>
      </TooltipInfoContent>
      {multipleValues ? (
        value.slice(0, 2).map((v, index) => (
          <TooltipValueContent
            key={`${v}-${index}`}
            variant="chip"
            className={valueContent}
          >
            {v}
          </TooltipValueContent>
        ))
      ) : (
        <TooltipValueContent variant="chip" className={valueContent}>
          {value}
        </TooltipValueContent>
      )}
    </TooltipItem>
  );
};

SeriesItem['displayName'] = 'ChartTooltip.SeriesItem';
